{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fremstiller 'mindst 1 år' som den generelle definition på varighed og siger, at man kan have ret, hvis nedsættelsen kan forventes at vare mindst 1 år. Det er ikke i overensstemmelse med kilderne, hvor varig som udgangspunkt betyder ingen væsentlig bedring inden for en længere årrække. Svaret tilføjer også en regel om at søge efter 6 måneder, som ikke findes i kilderne, og udelader, at et års symptomer forud for ansøgningen er udgangspunktet. Endelig udelades muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret mangler flere kritiske elementer. Der står intet om, at varigheden vedrører art og grad, og intet om, at nedsættelsen hverken af sig selv eller ved behandling bliver væsentligt bedre inden for en længere årrække. Der står heller ikke, at udgangspunktet er symptomer eller følger i mindst et år før ansøgningen, og intet om tidsbegrænset tillæg ved sandsynliggjort varighed."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret forsøger at besvare begge dele af spørgsmålet: hvornår en nedsættelse er varig, og hvad der gælder, hvis den ikke er varig fra begyndelsen. Indholdet er delvist forkert, men er ikke irrelevant."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner kun 'Uddannelses- og Forskningsministeriet' generelt. Det angiver ingen identificerbar bestemmelse, vejledningsafsnit eller lov, så de væsentlige udsagn kan ikke knyttes til en konkret kilde."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen identificerbar kilde, der kan vurderes. En generel henvisning til ministeriet er ikke nok."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen konkrete passager at vurdere støtte mod, så kriteriet kan ikke bedømmes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderbyggede regler: definitionen 'mindst 1 år' som kriterium for varighed, at man skal søge efter 6 måneder, og at man efter 6 måneder skal dokumentere forventet varighed på mindst 1 år. Kravet om 'objektivt dokumenteret' bekræftet af 'anden sundhedsfaglig person' passer heller ikke med kravet om lægefaglig dokumentation i form af journaler i § 37."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke 'som udgangspunkt' og 'omkring et år'. Det gør et år til et fast kriterium og udelader forbeholdet om, at tidsforløbet alene ikke afgør varigheden. Det fremgår heller ikke, at ettårsudgangspunktet gælder tiden før ansøgningen, eller at tidsbegrænset tillæg forudsætter sandsynliggjort varighed."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt usammenhængende. Det siger, at nedsættelsen er varig, hvis den kan forventes at vare mindst 1 år, og at man kan søge efter 6 måneder. Samtidig angives 'mere permanent karakter' som baggrund. Svaret skelner ikke klart mellem forventet varighed og tid forud for ansøgningen."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør vejledningens 'som udgangspunkt' og 'omkring et år' til faste krav med 'er varig, hvis' og 'skal søge ... når ... mindst 6 måneder'. Det angiver også den opdigtede 6-månedersregel som et krav."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret nævner, at nedsættelsen skal være varig for at give ret til tillægget, men med en forkert definition. Det nævner ikke, at der skal være tale om varig art og grad, eller at nedsættelsen ikke forventes at blive væsentligt bedre."
    },
    "A12": {
      "label": "no",
      "reason": "Svaret gengiver ikke vejledningens udgangspunkt om, at en ikke fra begyndelsen varig eller kronisk nedsættelse kan vurderes varig efter omkring et års varighed, og at der som udgangspunkt skal være symptomer eller følger i mindst et år forud for ansøgningen. Det angiver i stedet en forkert 6-måneders-regel og et fremadrettet krav om forventet varighed på 1 år."
    }
  },
  "overall_notes": "Svaret angiver ingen konkret kilde. Det er juridisk ukorrekt og ufuldstændigt, fordi det omdefinerer varighed som forventet varighed på mindst 1 år, opfinder en 6-månedersregel og udelader tidsbegrænset tillæg ved sandsynliggjort varighed. Det rammer dermed rubrikkens væsentlige fejl om, at et år fremstilles som en fast regel, og at det ikke fremgår, at ettårsudgangspunktet vedrører tiden før ansøgningen."
}

